def transform(grid):
    if not grid:
        return grid

    # Find uniform rows (all same value)
    uniform_rows = []
    for i, row in enumerate(grid):
        if len(set(row)) == 1:
            uniform_rows.append(i)

    if not uniform_rows:
        return grid

    # Find the first separator row
    first_separate_idx = uniform_rows[0]
    separator_val = grid[first_separate_idx][0]

    # Content block: rows before first separator
    content_rows = grid[0:first_separate_idx]

    # Build output: content + separator repeated
    output = []
    for i in range(len(grid)):
        pattern_idx = i % (len(content_rows) + 1)
        if pattern_idx < len(content_rows):
            output.append(content_rows[pattern_idx])
        else:
            output.append([separator_val] * len(content_rows[0]))

    return output

